pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the raw 32-byte words that would be used as the immutable args when packing the clone payload
    // we use two uint256 parameters so the fuzzer can choose different encoded addresses at offsets 0x0 and 0x14
    function testFuzz_property(uint256 word0, uint256 word1) public {
        // We reason about how owner() reads immutable args: reference reads address at offset 0x0.
        // Construct two addresses embedded into a 32-byte word sequence such that the address at offset 0x0
        // corresponds to the low 20 bytes of word0. We'll create calldata-like bytes and then compute
        // the expected owner address from word0. We then assert that c.owner() equals that address.
        // This is a universal property: for any word0/word1, reference returns address(from word0),
        // while mutant reading offset 0x14 will sometimes return address(from word1 low-20 bytes).

        // Bound nothing tightly; addresses are derived from the fuzzed words.
        address expectedOwner = address(uint160(word0));

        // The property we assert: c.owner() returns expectedOwner for all inputs.
        // Call the external public pure function owner() and assert its return equals expectedOwner.
        assertTrue(c.owner() == expectedOwner);
    }
}

