pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // We fuzz two addresses that would normally be encoded into immutable args by the factory/clone.
    // The correct contract returns the first encoded address (offset 0x0) as owner(); the mutant
    // that reads offset 0x14 would return the second encoded address instead for some inputs.
    function setUp() public { c = new C(); }

    function testFuzz_property(address a, address b) public {
        // Restrict to non-zero to avoid trivial equalities when both are zero address
        vm.assume(a != address(0) || b != address(0));

        // We cannot actually set immutable args on this direct instance. However, owner() is a pure
        // function that returns _getArgAddress(0x0) which depends only on calldata layout when used
        // on a clone with immutable args. To create a meaningful test that the reference always
        // returns the value at offset 0x0 while the mutant can return the value at 0x14,
        // we simulate by encoding calldata as if immutable args were present and calling owner via
        // delegatecall into the contract so it will execute the same pure logic reading calldata.
        // Build calldata where at offset _getImmutableArgsOffset()+0x0 sits `a` and at offset +0x14 sits `b`.

        // Construct calldata: layout is [padding..., immArgsBytes..., trailingLen(2 bytes)]
        // _getImmutableArgsOffset computes: calldatasize - (shr(240, calldataload(calldatasize-2)) + 2)
        // We'll place a 2-byte length at the end equal to immArgsLength, so offset points to start of immArgs.

        bytes memory imm = abi.encodePacked(a, b); // a at 0x00, b at 0x14
        // Ensure imm length fits; it's 0x28 = 40 bytes for two addresses
        bytes memory callData = bytes.concat(imm, hex"0028"); // 0x0028 = 40 length in 2 bytes

        // Now perform a low-level call to c with that calldata, invoking owner() logic via delegatecall pattern:
        // We use a small helper contract deployed here pattern-free: we'll use AddressCallHelper below.
        AddressCallHelper helper = new AddressCallHelper(address(c));

        // Call helper which will perform a DELEGATECALL into c with our constructed calldata and return data from owner()
        (bool ok, bytes memory ret) = address(helper).call(callData);

        // owner() is a function returning address (padded 32 bytes). The correct implementation (reading offset 0x0)
        // will return `a`. The mutant (reading offset 0x14) would return `b` for many inputs where a != b.
        // We assert the universal property that the observed return equals `a` (the value at offset 0x0).

        // Single assertion required: read c's behavior through its public surface via delegatecall path.
        // If call failed, consider that a test failure (should not for our setup). Convert return to address.
        assertTrue(ok && ret.length >= 32 && address(bytes20(ret[12:32])) == a);
    }
}

// Minimal helper that delegatecalls into the logic contract using calldata supplied to it.
// It does NOT define any functions; its fallback will delegatecall into the target with msg.data.
contract AddressCallHelper {
    address impl;
    constructor(address _impl) { impl = _impl; }
    fallback() external payable {
        (bool ok, ) = impl.delegatecall(msg.data);
        assembly {
            let ptr := mload(0x40)
            let size := returndatasize()
            returndatacopy(ptr, 0, size)
            switch ok
            case 0 { revert(ptr, size) }
            default { return(ptr, size) }
        }
    }
}

