pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the two addresses that would be encoded into immutable args; the fuzzer will try many pairs
    function testFuzz_property(address a, address b) public {
        // keep wide but avoid trivial equality where both addresses are identical
        vm.assume(a != address(0));
        vm.assume(b != address(0));

        // Build calldata that would correspond to immutable args encoding: pack a then b then some extra padding
        bytes memory imm = abi.encodePacked(a, b);

        // We cannot actually create a clone with these imm args here because C in setUp was created standalone.
        // But owner() of C is a pure function reading immutable args via _getArgAddress which depends on calldata layout
        // The way to test the invariant is to call owner() on a clone created with those immutable args.
        // Deploy a simple factory that clones C with given imm args using ClonesWithImmutableArgs clone mechanism

        // Create a minimal deployer that uses the same clone mechanism present in project; but per constraints
        // we must not import or redeclare the clone library; instead we deploy a lightweight helper CloneDeployer
        // that constructs a creation bytecode embedding the implementation and appends imm args — implement here.

        // Deploy CloneDeployer
        CloneDeployer deployer = new CloneDeployer();

        // Use deployer to create a clone of address(c) with imm args imm
        address payable cloneAddr = deployer.deployClone(address(c), imm);
        C clone = C(cloneAddr);

        // Now read owner() from the clone. The correct implementation returns address at offset 0x0 (a).
        // The mutant reading offset 0x14 would instead return b for these encodings — so the general rule:
        // owner() == a for the correct contract. We assert that owner() == a.

        assertTrue(clone.owner() == a);
    }
}

// Minimal helper that deploys a simple runtime that delegates to implementation and appends immutable args.
// This is a compact way to produce a clone whose owner() will read the provided immutable args.
contract CloneDeployer {
    // Deploy a minimal clone that uses DELEGATECALL to implementation and has the immutable args appended
    function deployClone(address implementation, bytes memory imm) external returns (address payable clone) {
        bytes memory creation;
        uint256 immLen = imm.length;
        // runtime code: simply delegatecall to implementation
        // runtime: 0x600080600a3d393df3  (very small runtime using delegatecall could be complex)
        // Simpler: use a standard minimal proxy runtime that forwards all calls to implementation using DELEGATECALL.
        // We'll assemble a standard EIP-1167-like minimal proxy (but using DELEGATECALL) and then append imm args after the runtime.

        bytes memory runtime = hex"363d3d373d3d3d363d73"; // part, we'll fill addr and rest
        // But assembling bytecode manually is tedious; instead build a standard deploy that contains implementation address and then runtime.

        // Use a simple method: create a contract whose fallback does delegatecall to implementation.
        // We'll construct creation code that stores implementation at code and returns runtime which does delegatecall.

        bytes memory code = abi.encodePacked(
            // constructor: copy runtime to memory and return
            hex"61", // PUSH2 <runtime_size>
            bytes2(uint16(45 + immLen)), // runtime size + imm appended
            hex"3d81600a3d39f3", // standard boilerplate to return runtime
            // runtime starts here (will be ~? bytes)
            // dispatcher: copy calldata to memory, delegatecall implementation, return whatever returned
            hex"366000573d52ff", // simplistic placeholder (not valid); instead we'll use a known working runtime below
            hex""
        );

        // To avoid writing complex proxy bytecode here, implement a trivial approach:
        // Deploy a contract whose code simply stores the imm args in its code area and has a public owner() that returns first 20 bytes of that stored data.
        // But we cannot redefine C's behavior; we must create a clone that when calling owner() leads into C's code which reads its immutable args from calldata offset computed from calldatasize; hence we need a runtime that forwards the call data plus the imm args appended as calldata to the implementation using DELEGATECALL.

        // Construct runtime that performs delegatecall to implementation with calldata located at memory and appended imm args at the end of calldata
        // For brevity and reliability in this test, we'll instead deploy a simple contract that on any call will perform a DELEGATECALL to implementation with the original calldata appended by imm bytes. This runtime is constructed below.

        bytes memory runtimeCode = buildRuntime(implementation, imm);
        // creation code: return runtimeCode
        bytes memory creationCode = abi.encodePacked(
            hex"60", // PUSH1
            bytes1(uint8(runtimeCode.length)),
            hex"60", // PUSH1
            bytes1(uint8(0x0)),
            hex"39f3", // CODECOPY, RETURN
            runtimeCode
        );

        assembly {
            let ptr := add(creationCode, 0x20)
            clone := create(0, ptr, mload(creationCode))
        }
        require(clone != address(0), "create failed");
    }

    function buildRuntime(address implementation, bytes memory imm) internal pure returns (bytes memory) {
        // We build runtime that does:
        // 1. copy calldata to mem
        // 2. append imm bytes from code to calldata buffer
        // 3. delegatecall to implementation with that calldata
        // 4. return returndata
        // This is somewhat involved; construct via known opcode sequence.

        // For simplicity and to stay within constraints, we implement a runtime which on call does the following in Yul-like pseudocode:
        // calldatasize -> cds
        // memcopy calldata to mem at 0
        // codecopy imm bytes from code to mem at cds
        // delegatecall(gas, implementation, 0, cds+immLen, 0, 0)
        // returndatacopy(0,0,returndatasize())
        // return(0, returndatasize())

        // We now craft bytecode for that. To avoid mistakes, we produce runtime via high-level assembly encoded bytes below (precalculated).
        // Precomputed runtime template assembled to perform the described actions.

        bytes memory rt;
        assembly {
            // allocate memory for rt
            rt := mload(0x40)
            mstore(0x40, add(rt, 0x100))
        }
        // Instead of crafting raw bytes (error-prone), fall back to a simpler but effective approach:
        // Deploy a small contract that has a single fallback which does:
        // (in solidity) fallback() external payable { assembly { let cd := calldatasize() let ptr := mload(0x40) calldatacopy(ptr, 0, cd) calldatacopy(add(ptr, cd), add(instructionoffset, immOffset), immLen) let success := delegatecall(gas(), implementation, ptr, add(cd, immLen), 0, 0) returndatacopy(ptr, 0, returndatasize()) if iszero(success) { revert(ptr, returndatasize()) } return(ptr, returndatasize()) } }
        // But we cannot compile Solidity here. Given complexity and time, provide a minimal working known pattern for delegate-proxy with appended data is non-trivial.

        revert("buildRuntime not implemented");
    }
}

