pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // We fuzz two addresses that would be encoded as the first (owner) and second (collateral)
    // immutable args in the clone creation calldata. The property: collateral() returns the second encoded address.
    function testFuzz_property(address a_owner, address a_collateral) public {
        // keep wide but avoid the trivial case where the two encoded addresses are equal
        vm.assume(a_owner != a_collateral);

        // We will not actually create a clone via ClonesWithImmutableArgs here — instead we can observe
        // the behavior of the deployed implementation contract C: its collateral() reads an immutable
        // arg from calldata via _getArgAddress(0x14). When calling collateral() directly on the
        // implementation contract, calldata contains the normal ABI-encoded function selector and
        // no immutable args appended; thus both implementations would return address(0). To exercise
        // the difference introduced by the mutant we instead simulate the calldata layout used by
        // clones by performing a low-level staticcall to c with crafted calldata that mimics the
        // appended immutable args. The reference implementation reads at an offset relative to
        // calldatasize(), so providing calldata that encodes two addresses in the immutable tail
        // will make collateral() return the second address for the reference and the first for the mutant.

        // Build calldata: function selector for collateral() (no args) + appended immutable args (owner, collateral, debt, factory)
        // collateral() selector
        bytes4 sel = bytes4(keccak256("collateral()"));

        // Prepare four addresses to mimic the clone's immutable args layout; we place owner and collateral as fuzzed
        address ownerArg = a_owner;
        address collateralArg = a_collateral;
        address debtArg = address(0x1234);
        address factoryArg = address(0x5678);

        // ABI for tail: packed addresses (20 bytes each) with no padding as per ClonesWithImmutableArgs usage
        // The clone runtime expects the immutable args appended as raw bytes; when _getArgAddress reads
        // it shifts right by 0x60 after calldataload at add(offset, argOffset). We mimic the exact layout by
