        assembly { mstore(add(callData, 32), shl(224, sel)) }
        // copy imm
        for (uint256 i = 0; i < immLen; i += 32) {
            bytes32 chunk;
            assembly { chunk := mload(add(add(imm, 32), i)) }
            assembly { mstore(add(add(callData, 32), add(4, i)), chunk) }
        }
        // write trailer as last 2 bytes (big endian as used by clone code via calldataload and shr 240)
        // The clone code reads: shr(240, calldataload(sub(calldatasize(), 2))) => it loads a 32-byte word ending with the two trailer bytes,
        // then shifts right by 240 to get the uint16 trailer. That implies the trailer must be placed in the lowest-order 2 bytes.
        assembly {
            // load final word position
            let lastPos := add(add(callData, 32), add(4, immLen))
            // store trailer into the low 2 bytes of that word
            // read existing 32 bytes (should be zero), or write trailer directly
            mstore8(sub(lastPos, 1), byte(1, trailer))
            mstore8(lastPos, byte(0, trailer))
        }

        // Now perform staticcall to c with that calldata to invoke debt(); debt() is pure, so staticcall is fine.
        (bool ok, bytes memory ret) = address(c).staticcall(callData);

        // If call reverted, treat as failure of invocation; but both reference and mutant won't revert for this getter.
        // decode returned address if ok
        address returned = address(0);
        if (ok && ret.length >= 32) {
            returned = address(uint160(uint256(bytes32(ret))));
        }

        // Compute expected address per reference: address(uint160(shr(0x60, rawWord)))
        address expected = address(uint160(uint256(rawWord >> 0x60)));

        // The general property: for any rawWord, reference returns expected; mutant will differ when top 12 bytes nonzero.
        // Assert that c.debt() (called with calldata encoding that rawWord as the immutable `debt` arg) equals expected.
        assertTrue(returned == expected);
    }
}

